                d[j] = d[i] + R[(i, j)][1]
                onceki[j] = i
                son = j
        if son is None:
            return None
    v = son                                # dongunun icine gir
    for _ in range(len(dugumler)):
        v = onceki[v]
    dongu = [v]
    u = onceki[v]
    while u != v:
        dongu.append(u)
        u = onceki[u]
    dongu.reverse()
    return dongu

