def en_kisa(arcs, lam, s, t):
    INF = float('inf')
    d = {v: INF for v in dugumler}
    d[s] = 0
    onceki = {}
    for _ in range(len(dugumler)):
        for (i, j) in sorted(arcs):
            w = arcs[(i, j)][0] + lam.get((i, j), 0)
            if d[i] + w < d[j]:
                d[j] = d[i] + w
                onceki[j] = i
    yol = [t]
    while yol[-1] != s:
        yol.append(onceki[yol[-1]])
    yol.reverse()
    return d[t], yol

def lagrange(arcs, urunler, lam):
    L = 0
    yollar = []
    for (s, t, dmd) in urunler:
        uz, yol = en_kisa(arcs, lam, s, t)
        L += dmd * uz
        yollar.append(yol)
    L -= sum(lam.get(k, 0) * arcs[k][1] for k in arcs)
    return L, yollar

def yuk(arcs, urunler, yollar):
    y = {k: 0 for k in arcs}
    for (s, t, dmd), p in zip(urunler, yollar):
        for i in range(len(p) - 1):
            y[(p[i], p[i + 1])] += dmd
    return y

